'use strict';
const fs=require('fs'); const path=require('path');
const root=process.env.GITHUB_WORKSPACE||process.cwd(); const qdir=path.join(root,'qualification','learning');
const evidenceDir=path.join(process.env.RUNNER_TEMP||root,'learning-dependency-adjudication-batch-02-evidence'); fs.mkdirSync(evidenceDir,{recursive:true});
const load=(n)=>JSON.parse(fs.readFileSync(path.join(qdir,n),'utf8'));
const base=(p)=>path.basename(p);
const fail=(code,detail='')=>{const failure=detail?`${code}:${detail}`:code;fs.writeFileSync(path.join(evidenceDir,'failure-summary.json'),JSON.stringify({subject_sha:process.env.GITHUB_SHA||'LOCAL',result_class:'FAIL',failure},null,2)+'\n');throw new Error(failure);};
const contract=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001C-DEPENDENCY-EVIDENCE-ADJUDICATION-CONTRACT-044.json');
const prior=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001C-DEPENDENCY-EVIDENCE-ADJUDICATION-BATCH-01-CANDIDATE-044A.json');
const candidate=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001C-DEPENDENCY-EVIDENCE-ADJUDICATION-BATCH-02-CANDIDATE-045A.json');
const structural=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001A-FULL-GRAPH-CLOSURE-CANDIDATE-024A.json');
const assessment=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001B-ASSESSMENT-TARGET-FULL-CLOSURE-CANDIDATE-042A.json');
if(candidate.base_control_head!=='93358f5eec403b9ea3ac190dc7fac32d8b3c56f2') fail('CONTROL_HEAD_DRIFT');
if(candidate.assessment_full_closure_subject!==contract.inputs.assessment_full_closure_subject||candidate.structural_closure_subject!==contract.inputs.structural_closure_subject) fail('CLOSURE_SUBJECT_DRIFT');
const topologyPaths=[structural.cumulative_inputs.domain_i_base,...structural.cumulative_inputs.bounded_candidates]; const universe=[]; const byId=new Map(); const parents=new Set();
for(const p of topologyPaths){const t=load(base(p)); for(const s of t.subskills||[]) parents.add(s.parent_requirement_id); for(const u of t.unresolved_dependency_candidates||[]){if(u.admission_status!=='UNRESOLVED__NOT_CANONICAL') fail('SOURCE_CANDIDATE_STATUS',u.candidate_id); const x={...u,source_topology_artifact:p}; universe.push(x); byId.set(x.candidate_id,x);}}
if(universe.length!==46) fail('UNIVERSE_COUNT',String(universe.length)); if(parents.size!==66) fail('SUBSKILL_COUNT',String(parents.size));
const allTargets=[]; for(const n of assessment.assessment_batches){const b=load(n); allTargets.push(...b.targets);} const targetParents=new Set(allTargets.map(t=>t.parent_requirement_id)); if(allTargets.length!==66||targetParents.size!==66) fail('ASSESSMENT_COUNT');
if(prior.dispositions.length!==5||candidate.dispositions.length!==5) fail('BATCH_COUNT'); const priorIds=prior.dispositions.map(d=>d.candidate_id); const ids=candidate.dispositions.map(d=>d.candidate_id); if(JSON.stringify(priorIds)!==JSON.stringify(universe.slice(0,5).map(u=>u.candidate_id))) fail('PRIOR_ORDER'); if(JSON.stringify(ids)!==JSON.stringify(universe.slice(5,10).map(u=>u.candidate_id))) fail('SELECTION_ORDER'); if(ids.some(id=>priorIds.includes(id))) fail('REPLAY');
const allowed=new Set(contract.allowed_dispositions); let admitted=0,rejected=0,unresolved=0,deferred=0; const seen=new Set();
for(const d of candidate.dispositions){const src=byId.get(d.candidate_id); if(!src) fail('UNKNOWN',d.candidate_id); if(seen.has(d.candidate_id)) fail('DUPLICATE',d.candidate_id); seen.add(d.candidate_id); if(d.from_id!==src.from_id||d.to_id!==src.to_id||d.source_topology_artifact!==src.source_topology_artifact) fail('SOURCE_DRIFT',d.candidate_id); if(!allowed.has(d.disposition)) fail('DISPOSITION',d.candidate_id); if(!targetParents.has(d.from_id)||!targetParents.has(d.to_id)) fail('ASSESSMENT_ENDPOINT',d.candidate_id); if(!Array.isArray(d.evidence_refs)||d.evidence_refs.length<4) fail('EVIDENCE_REFS',d.candidate_id); if(typeof d.rationale!=='string'||d.rationale.length<40) fail('RATIONALE',d.candidate_id); if(d.disposition==='REJECT_AS_HARD_PREREQUISITE'){rejected++; if(!d.material_dependency_test||d.material_dependency_test.target_independently_performable!==true||String(d.material_dependency_test.basis||'').length<40) fail('REJECTION_TEST',d.candidate_id);} else if(d.disposition==='REMAIN_UNRESOLVED__NOT_CANONICAL') unresolved++; else if(d.disposition==='DEFER_TO_SEPARATE_HUMAN_OR_SME_EVIDENCE') deferred++; else admitted++;}
if(admitted!==0||(candidate.admitted_prerequisite_edges||[]).length!==0) fail('UNEXPECTED_ADMISSION'); const bs=candidate.batch_summary; if(bs.admitted!==admitted||bs.rejected_as_hard_prerequisite!==rejected||bs.remain_unresolved_not_canonical!==unresolved||bs.deferred_to_human_or_sme!==deferred) fail('SUMMARY');
for(const [k,v] of Object.entries(contract.evidence_boundaries)) if(candidate.evidence_boundaries[k]!==v) fail('BOUNDARY',k);
const summary={subject_sha:process.env.GITHUB_SHA||'LOCAL',result_class:'PASS',batch_index:2,unresolved_candidate_universe_count:universe.length,cumulative_disposition_count:10,selected_candidate_count:5,dispositions:{admitted,rejected_as_hard_prerequisite:rejected,remain_unresolved_not_canonical:unresolved,deferred_to_human_or_sme:deferred},remaining_candidate_count:36,frozen_requirement_count:66,frozen_subskill_count:66,frozen_assessment_target_count:66,next_objective:candidate.next_batch_on_pass,authority_boundary:'HOSTED_MACHINE_EVIDENCE_ONLY__NO_HUMAN_SME_A01_NATIVE_OR_PRODUCTION_AUTHORITY_INFERRED'}; fs.writeFileSync(path.join(evidenceDir,'qualification-summary.json'),JSON.stringify(summary,null,2)+'\n'); console.log(JSON.stringify(summary));
